"""Construct the minimal carrier enlargement retaining x1/x5 endpoint lines."""
import json,subprocess,tempfile
from pathlib import Path
R=Path(__file__).resolve().parents[2];s=R/'research/voevodsky/check_d03_exit_spatial_kernel.rs';e=Path(tempfile.gettempdir())/(s.stem+'.exe');subprocess.run(['rustc','--edition=2021','-D','warnings','-O',str(s),'-o',str(e)],check=True);x=json.loads(subprocess.check_output([str(e)],text=True));f=x['factorization_test']
checks={'inverse_transgression':f['inverse_transgression'].startswith('PASS'),'dual_column':f['dual_cell_column'].startswith('PASS'),'loaded_column':f['occurrence_loaded_column'].startswith('PASS'),'q0q2_Q_zero':'ZERO' in f['actual_carrier_q_image'],'claimed_lift_fails':f['claimed_loaded_road_Tor_column']=='FALSIFIED','no_inversions':f['inversions']=='none'}
assert all(checks.values()),checks
out={'schema':'marici.voevodsky.CR1-enlarged-endpoint-line-correspondence.v1','action':'CR1ALPHA2a1b_construct_endpoint_line_enlarged_carrier','outcome':'+-','constructed':{'generic_leg':'canonical saturated inverse transgression e3 <-> F03','endpoint_column':'d(e3)=-x1*q0+x5*q2','retained_lines':['I_x1 on q0','I_x5 on q2','external Rees conormal [t3]'],'carrier_shadow':'primitive column (-q0,+q2) after principal-line evaluation'},'unresolved':'extraordinary map from q0,q2 endpoint lines to actual reciprocal/BM road Tor1 costalks','negative_controls':['q0 and q2 themselves have zero ordinary Q image','none of e3,q0,q2 has internal x3 normal support','[t3] must remain external and cannot be manufactured by beta3 on these cells'],'produces':['endpoint_line_enlarged_inverse_transgression_carrier'],'next':'CR1ALPHA2a1c_construct_variance_changing_q0_q2_to_road_Tor1_map','metric_delta':{'active_alpha_candidate_paths':1,'new_typed_interfaces':1,'candidate_endpoint_carriers':1,'geometrically_complete_paths':0},'checks':checks,'passed':True};p=R/'research/voevodsky/results/CR1_enlarged_endpoint_line_correspondence.json';p.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({'passed':True,'outcome':'+-','carrier_candidate':True,'active_alpha_paths':1,'next':out['next']}))
